    'Sales pipeline CRM', 'Meta inbox management', 'Omni channel communication', 
    'Customer support automation', 'Lead generation', 'Follow-up automation',
    'Marketing automation', 'Customer engagement', 'Inquiry management',
    'Booking management', 'Appointment scheduling', 'Order tracking',
    'Customer feedback', 'Review management', 'Loyalty program'
];

// Create a more specific prompt that forces diversity
const industryExamples = allIndustries.slice(0, 15).join(', ');
const cityExamples = allCities.slice(0, 10).join(', ');

const user = `Generate ${cfg.limits.keywordsPerRun} COMPLETELY UNIQUE Google Maps search keywords for Pakistan.

IMPORTANT RULES:
1. DO NOT repeat the same industry or city in more than 2 keywords
2. Mix different cities and industries
3. Avoid these common keywords if possible: "Shopify store", "Real estate agency", "Digital marketing agency"
4. Include a diverse mix of industries like: ${industryExamples}
5. Include diverse cities like: ${cityExamples}
6. Each keyword must be unique and searchable on Google Maps
7. Keywords should target businesses that need WhatsApp CRM, chatbots, or sales automation

Return ONLY JSON: {"keywords":[{"keyword":"...","city":"...","industry":"...","intent":"..."}]}`;

let parsed;
let usedFallback = false;

try {
    const key = cfg.deepseek.apiKey;
    if (!key || key === 'PASTE_DEEPSEEK_API_KEY_HERE') {
        throw new Error('Configure DeepSeek API key');
    }

    // Use higher temperature and add randomness with date seed
    const temperature = 1.2 + (Math.random() * 0.3); // 1.2 to 1.5
    const seed = dateSeed + Math.floor(Math.random() * 100);

    const res = await this.helpers.httpRequest({
        method: 'POST',
        url: cfg.deepseek.apiUrl,
        headers: {
            Authorization: `Bearer ${key}`,
            'Content-Type': 'application/json'
        },
        body: {
            model: cfg.deepseek.model,
            temperature: temperature,
            messages: [
                { 
                    role: 'system', 
                    content: `You are a Pakistani B2B sales director for SRLINES. Generate EXTREMELY DIVERSE keywords. Today's seed is ${seed}. Focus on unique combinations.` 
                },
                { 
                    role: 'user', 
                    content: user 
                }
            ],
            response_format: { type: 'json_object' }
        },
        json: true,
        timeout: 120000
    });

    parsed = JSON.parse(res.choices?.[0]?.message?.content || '{}');

    // Check if we got enough unique keywords
    const keywords = parsed.keywords || [];
    const uniqueIndustries = new Set(keywords.map(k => k.industry));
    const uniqueCities = new Set(keywords.map(k => k.city));

    if (uniqueIndustries.size < 5 || uniqueCities.size < 3) {
        console.log('⚠️ Not enough diversity in API response, using fallback');
        usedFallback = true;
        throw new Error('Not enough diversity');
    }

} catch (e) {
    console.log('Using enhanced fallback with more diversity:', e.message);
    usedFallback = true;

    // Enhanced fallback with better randomization
    const shuffledCities = [...allCities];
    const shuffledIndustries = [...allIndustries];
    const shuffledIntents = [...allIntents];

    // Use multiple seeds for better shuffling
    const seed1 = dateSeed + Math.floor(Math.random() * 1000);
    const seed2 = dateSeed + 500 + Math.floor(Math.random() * 1000);
    const seed3 = dateSeed + 1000 + Math.floor(Math.random() * 1000);

    // Shuffle with multiple passes for better randomness
    for (let pass = 0; pass < 3; pass++) {
        const currentSeed = [seed1, seed2, seed3][pass % 3];
        for (let i = shuffledCities.length - 1; i > 0; i--) {
            const j = (i + currentSeed) % (i + 1);
            [shuffledCities[i], shuffledCities[j]] = [shuffledCities[j], shuffledCities[i]];
        }
        for (let i = shuffledIndustries.length - 1; i > 0; i--) {
            const j = (i + currentSeed * 2) % (i + 1);
            [shuffledIndustries[i], shuffledIndustries[j]] = [shuffledIndustries[j], shuffledIndustries[i]];
        }
    }

    // Generate keywords with forced diversity
    const numKeywords = cfg.limits.keywordsPerRun || 30;
    const selectedIndustries = [];
    const selectedCities = [];

    // Ensure we don't repeat industries and cities too often
    for (let i = 0; i < numKeywords; i++) {
        const industryIndex = (i * 3 + 1) % shuffledIndustries.length;
        const cityIndex = (i * 7 + 5) % shuffledCities.length;
        const intentIndex = (i * 11 + 3) % shuffledIntents.length;

        selectedIndustries.push(shuffledIndustries[industryIndex]);
        selectedCities.push(shuffledCities[cityIndex]);
    }

    parsed = {
        keywords: Array.from({ length: numKeywords }, (_, i) => ({
            keyword: `${selectedIndustries[i]} in ${selectedCities[i]}`,
            city: selectedCities[i],
            industry: selectedIndustries[i],
            intent: shuffledIntents[i % shuffledIntents.length]
        }))
    };
}

// Deduplicate and ensure diversity
const seen = new Set();
const seenIndustries = new Set();
const seenCities = new Set();
const results = [];

const keywords = parsed.keywords || [];

for (const k of keywords) {
    const keyword = String(k.keyword || '').trim();
    const industry = String(k.industry || '').trim();
    const city = String(k.city || '').trim();

    if (!keyword) continue;

    const key = keyword.toLowerCase();
    const industryKey = industry.toLowerCase();
    const cityKey = city.toLowerCase();

    // Skip duplicates
    if (seen.has(key)) continue;

    // Try to maintain diversity - skip if we have too many of same industry or city
    const industryCount = seenIndustries.has(industryKey) ? 0 : 1;
    const cityCount = seenCities.has(cityKey) ? 0 : 1;

    // Allow up to 3 keywords per industry/city if we have enough total
    const maxPerIndustry = Math.min(3, Math.ceil(keywords.length / 10) + 1);
    const maxPerCity = Math.min(3, Math.ceil(keywords.length / 10) + 1);

    // Only enforce diversity if we have enough keywords
    if (results.length > 5 && results.length < keywords.length - 2) {
        // Check if industry is overused
        let industryOverused = false;
        let cityOverused = false;

        let industryCountTotal = 0;
        let cityCountTotal = 0;
        for (const r of results) {
            if (r.industry?.toLowerCase() === industryKey) industryCountTotal++;
            if (r.city?.toLowerCase() === cityKey) cityCountTotal++;
        }

        if (industryCountTotal >= maxPerIndustry) industryOverused = true;
        if (cityCountTotal >= maxPerCity) cityOverused = true;

        // If overused, only add if we have very few keywords left
        if ((industryOverused || cityOverused) && results.length < keywords.length - 2) {
            continue;
        }
    }

    seen.add(key);
    seenIndustries.add(industryKey);
    seenCities.add(cityKey);

    results.push({
        json: {
            ...cfg,
            keyword: keyword,
            keywordCity: city || '',
            keywordIndustry: industry || '',
            keywordIntent: k.intent || 'commercial',
            keywordDiversity: 'high'
        }
    });

    // Stop if we have enough
    if (results.length >= (cfg.limits.keywordsPerRun || 30)) break;
}

// If we don't have enough keywords, generate more with fallback
if (results.length < (cfg.limits.keywordsPerRun || 30)) {
    console.log(`⚠️ Only generated ${results.length} keywords. Adding more from fallback.`);

    const remaining = (cfg.limits.keywordsPerRun || 30) - results.length;
    const fallbackCities = allCities.slice(10, 10 + remaining * 2);
    const fallbackIndustries = allIndustries.slice(15, 15 + remaining * 2);

    for (let i = 0; i < remaining && i < fallbackCities.length && i < fallbackIndustries.length; i++) {
        const keyword = `${fallbackIndustries[i % fallbackIndustries.length]} in ${fallbackCities[i % fallbackCities.length]}`;
        const key = keyword.toLowerCase();

        if (!seen.has(key)) {
            seen.add(key);
            results.push({
                json: {
                    ...cfg,
                    keyword: keyword,
                    keywordCity: fallbackCities[i % fallbackCities.length],
                    keywordIndustry: fallbackIndustries[i % fallbackIndustries.length],
                    keywordIntent: 'lead generation',
                    keywordDiversity: 'fallback'
                }
            });
        }
    }
}

// Store used keywords history to avoid repeats in future runs
if (results.length > 0) {
    const newKeywords = results.map(r => r.json.keyword.toLowerCase());
    data[usedKeywordsKey] = [...data[usedKeywordsKey], ...newKeywords].slice(-500); // Keep last 500
}

// Sort by diversity flag to prioritize diverse keywords
results.sort((a, b) => {
    if (a.json.keywordDiversity === 'high' && b.json.keywordDiversity !== 'high') return -1;
    if (a.json.keywordDiversity !== 'high' && b.json.keywordDiversity === 'high') return 1;
    return 0;
});

console.log(`✅ Generated ${results.length} diverse keywords`);

// Always return something
if (results.length === 0) {
    // Ultra fallback with maximum diversity
    const ultraFallback = [
        { keyword: 'Car dealer in Faisalabad', city: 'Faisalabad', industry: 'Auto dealer', intent: 'WhatsApp inquiries' },
        { keyword: 'Pharmacy in Peshawar', city: 'Peshawar', industry: 'Pharmacy', intent: 'Order management' },
        { keyword: 'Gym in Islamabad', city: 'Islamabad', industry: 'Gym', intent: 'Membership management' },
        { keyword: 'Digital marketing agency in Lahore', city: 'Lahore', industry: 'Digital marketing', intent: 'Lead generation' },
        { keyword: 'Salon in Rawalpindi', city: 'Rawalpindi', industry: 'Salon', intent: 'Booking management' }
    ];

    return ultraFallback.map(k => ({
        json: {
            ...cfg,
            keyword: k.keyword,
            keywordCity: k.city,
            keywordIndustry: k.industry,
            keywordIntent: k.intent
        }
    }));
}

return results;

